import{JOSENotSupported}from"../util/errors.js";import{checkSigCryptoKey}from"./crypto_key.js";import{invalidKeyInput}from"./invalid_key_input.js";export function checkKeyLength(e,t){if(e.startsWith("RS")||e.startsWith("PS")){const{modulusLength:r}=t.algorithm;if("number"!=typeof r||r<2048)throw new TypeError(`${e} requires key modulusLength to be 2048 bits or larger`)}}function subtleAlgorithm(e,t){const r=`SHA-${e.slice(-3)}`;switch(e){case"HS256":case"HS384":case"HS512":return{hash:r,name:"HMAC"};case"PS256":case"PS384":case"PS512":return{hash:r,name:"RSA-PSS",saltLength:parseInt(e.slice(-3),10)>>3};case"RS256":case"RS384":case"RS512":return{hash:r,name:"RSASSA-PKCS1-v1_5"};case"ES256":case"ES384":case"ES512":return{hash:r,name:"ECDSA",namedCurve:t.namedCurve};case"Ed25519":case"EdDSA":return{name:"Ed25519"};case"ML-DSA-44":case"ML-DSA-65":case"ML-DSA-87":return{name:e};default:throw new JOSENotSupported(`alg ${e} is not supported either by JOSE or your javascript runtime`)}}async function getSigKey(e,t,r){if(t instanceof Uint8Array){if(!e.startsWith("HS"))throw new TypeError(invalidKeyInput(t,"CryptoKey","KeyObject","JSON Web Key"));return crypto.subtle.importKey("raw",t,{hash:`SHA-${e.slice(-3)}`,name:"HMAC"},!1,[r])}return checkSigCryptoKey(t,e,r),t}export async function sign(e,t,r){const n=await getSigKey(e,t,"sign");checkKeyLength(e,n);const s=await crypto.subtle.sign(subtleAlgorithm(e,n.algorithm),n,r);return new Uint8Array(s)}export async function verify(e,t,r,n){const s=await getSigKey(e,t,"verify");checkKeyLength(e,s);const a=subtleAlgorithm(e,s.algorithm);try{return await crypto.subtle.verify(a,s,r,n)}catch{return!1}}